#!/bin/sh
# Orchestrator git hook. Generated by Orchestrator; edits are overwritten.
#
# A session worktree points core.hooksPath (worktree scope only) at this
# directory. Every hook name is a copy of this script. prepare-commit-msg and
# commit-msg add Orchestrator's Co-authored-by trailer; every hook then hands
# off to the hook the repository itself would have run (husky, lint-staged,
# .git/hooks), so the repository's own hooks keep working.

hook=$(basename "$0")
here=$(cd "$(dirname "$0")" 2>/dev/null && pwd -P)

# original_hook prints the hook the repository would run without Orchestrator:
# a hooksPath this worktree's config had before Orchestrator replaced it, else
# core.hooksPath from the repository, global or system config (read live, so a
# hooksPath that husky sets after the session started still runs), else the
# shared hooks directory.
original_hook() {
	dir=$(git config --worktree --type=path --get orchestrator.originalHooksPath 2>/dev/null)
	if [ -z "$dir" ]; then
		dir=$(git config --type=path --show-scope --get-all core.hooksPath 2>/dev/null |
			awk -F '\t' '$1 != "worktree" { v = $2 } END { print v }')
	fi
	if [ -z "$dir" ]; then
		dir=$(git rev-parse --git-common-dir 2>/dev/null) || return 0
		dir="$dir/hooks"
	fi
	resolved=$(cd "$dir" 2>/dev/null && pwd -P) || return 0
	[ "$resolved" = "$here" ] && return 0
	if [ -f "$resolved/$hook" ] && [ -x "$resolved/$hook" ]; then
		printf '%s\n' "$resolved/$hook"
	fi
}

# replaying reports whether git is replaying existing commits (a rebase or a
# cherry-pick). Those commits were written before, often by someone else, so
# they keep the message they had. A revert is a new commit and is credited.
# While a rebase is stopped (an edit stop, or an --exec step) every commit is
# skipped, including a new one the agent writes there: telling it apart from a
# replayed pick needs rebase-merge/done bookkeeping, not worth it for that case.
replaying() {
	for name in rebase-merge rebase-apply CHERRY_PICK_HEAD; do
		path=$(git rev-parse --git-path "$name" 2>/dev/null) || continue
		[ -e "$path" ] && return 0
	done
	return 1
}

# has_message reports whether the message file holds anything besides comment
# lines and whitespace. The comment string is matched literally. With
# core.commentChar=auto git picks a character the message does not start a
# line with, so any of git's candidates counts as a comment there; at worst
# that skips the trailer, never breaks the commit. `git commit -v` appends a
# diff below a scissors line; it is not message.
has_message() {
	cs=$(git config --get core.commentString 2>/dev/null) ||
		cs=$(git config --get core.commentChar 2>/dev/null) || cs='#'
	[ -n "$cs" ] || cs='#'
	# The comment string goes through the environment: awk -v would treat its
	# backslashes as escapes.
	ORCHESTRATOR_CS=$cs awk '
		function comment(line,   i) {
			if (cs != "auto") return index(line, cs) == 1
			for (i = 1; i <= length(auto); i++)
				if (substr(line, 1, 1) == substr(auto, i, 1)) return 1
			return 0
		}
		BEGIN { cs = ENVIRON["ORCHESTRATOR_CS"]; auto = "#;@!$%^&|:"; found = 0 }
		comment($0) && index($0, "------------------------ >8 ------------------------") { exit }
		!comment($0) && $0 ~ /[^ \t\r]/ { found = 1; exit }
		END { exit !found }
	' "$1"
}

# insert_trailer adds trailer $2 to message file $1 with none of the person's
# trailer.* config: no separators, placement, or trailer.<token>.cmd that
# could rewrite or duplicate it. git runs outside any repository with the
# global and system config switched off; only the comment string carries over,
# so comment lines and a `commit -v` scissors line are still recognised.
# --no-divider: a "---" line in the body is not a patch divider here.
insert_trailer() {
	case "$1" in /*) file=$1 ;; *) file=$PWD/$1 ;; esac
	trailer=$2
	comment=$(git config --get core.commentString 2>/dev/null) ||
		comment=$(git config --get core.commentChar 2>/dev/null) || comment=
	(
		unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_COMMON_DIR GIT_PREFIX \
			GIT_CONFIG GIT_CONFIG_PARAMETERS GIT_CONFIG_COUNT
		GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1 GIT_CEILING_DIRECTORIES=$(dirname "$here")
		export GIT_CONFIG_GLOBAL GIT_CONFIG_NOSYSTEM GIT_CEILING_DIRECTORIES
		cd "$here" || exit 0
		set --
		if [ -n "$comment" ] && [ "$comment" != auto ]; then
			if [ "${#comment}" -eq 1 ]; then
				set -- -c "core.commentChar=$comment"
			else
				set -- -c "core.commentString=$comment"
			fi
		fi
		git "$@" interpret-trailers --in-place --no-divider --where end \
			--if-exists addIfDifferent --if-missing add --trailer "$trailer" "$file"
	) 2>/dev/null || true
}

# add_trailer adds the trailer to the message file in $1. $2 is the commit
# source git passes to prepare-commit-msg (empty for commit-msg).
add_trailer() {
	msg=$1
	[ -n "$msg" ] && [ -f "$msg" ] || return 0
	[ "$2" = merge ] && return 0
	# A merge commit (git merge, or a conflicted merge being concluded).
	merge_head=$(git rev-parse --git-path MERGE_HEAD 2>/dev/null)
	[ -n "$merge_head" ] && [ -f "$merge_head" ] && return 0
	replaying && return 0
	coauthor=$(git config --get orchestrator.coauthor 2>/dev/null)
	[ -n "$coauthor" ] || return 0
	# -m and -F messages are taken as written: nothing in them is a comment.
	# Otherwise, with nothing written yet the editor is about to open; commit-msg
	# adds the trailer after it closes, and an empty message still aborts.
	if [ "$2" != message ]; then
		has_message "$msg" || return 0
	elif ! grep -q '[^[:space:]]' "$msg"; then
		return 0
	fi
	insert_trailer "$msg" "Co-authored-by: $coauthor"
}

original=$(original_hook)
case "$hook" in
prepare-commit-msg | commit-msg)
	if [ -n "$original" ]; then
		"$original" "$@" || exit $?
	fi
	add_trailer "$1" "$2"
	exit 0
	;;
esac
if [ -n "$original" ]; then
	exec "$original" "$@"
fi
exit 0
